            sliceEnd = now + SLICE_SECONDS
        end
        if currentTask then
            local ok, err = pcall(currentTask.step)
            if not ok then
                log(S(166) .. currentTask.name .. S(403) .. tostring(err))
            end
        end
    end)
end
